def hydrate_time(nanoseconds, tz=None):
    """Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Nanoseconds since midnight
    :type nanoseconds: int
    :param tz: Optional timezone info
    :type tz: datetime.tzinfo, None
    :return: datetime.time
    """
    try:
        ns = int(nanoseconds)
    except Exception as exc:
        raise TypeError("nanoseconds must be an integer") from exc

    if ns < 0:
        raise ValueError("nanoseconds cannot be negative")

    total_seconds, remaining_ns = divmod(ns, 1_000_000_000)
    micros = remaining_ns // 1000
    total_seconds %= 86400
    hour, remainder = divmod(total_seconds, 3600)
    minute, second = divmod(remainder, 60)

    if tz and hasattr(tz, 'utcoffset'):
        return time(hour, minute, second, micros, tzinfo=tz)
    return time(hour, minute, second, micros)

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None

    # Validate the type of the input.
    try:
        # Attempt to use isinstance first; falls back to attribute checks if Point is not imported.
        if not isinstance(value, Point):
            raise TypeError(f"Expected a Point instance, got {type(value).__name__}")
    except NameError:
        # If the Point class is not defined in the current namespace, fall back to duck typing.
        if not hasattr(value, "x") or not hasattr(value, "y"):
            raise TypeError("Expected an object with 'x' and 'y' attributes representing a Point")
        # No further validation needed; value will be treated as a Point-like object.

    # Serialize the Point to a simple data structure suitable for storage or transmission.
    result = {"x": getattr(value, "x"), "y": getattr(value, "y")}

    # Include third coordinate if present.
    if hasattr(value, "z"):
        result["z"] = getattr(value, "z")

    return result

