    """poor man's version comparison"""
    import re
    if not s:
        return ()
    # Extract all digit sequences from the string and convert them to integers.
    # This method is intentionally simple and does not support complex
    # semantic versioning nuances such as prerelease or build metadata.
    parts = re.findall(r'\d+', s)
    return tuple(int(part) for part in parts)

