                try:
                    import yaml  # type: ignore
                except ImportError as e:
                    raise ImportError(
                        f"YAML support requires PyYAML, but it could not be imported. "
                        f"Spec file: {spec_path}"
                    ) from e
                spec_data = yaml.safe_load(f)
            else:
                spec_data = json.load(f)
    except Exception as e:
        raise RuntimeError(f"Failed to load plugin spec from {spec_path}: {e}") from e

    if not isinstance(spec_data, dict):
        raise ValueError(f"Spec file {spec_path} does not contain a top‑level JSON object")

    # Recursive function to flatten nested dictionaries
    def _flatten(d, parent_key=""):
        flat = {}
        for key, value in d.items():
            compound_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                flat.update(_flatten(value, compound_key))
            else:
                flat[compound_key] = value
        return flat

    return _flatten(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
        env_var = "CONFIG_PATH"
        # Check if the environment variable is already set
        if not os.getenv(env_var):
            # Prefer a config_path attribute on the instance if it exists
            default_path = getattr(self, "config_path", None) or os.getcwd()
            # Only set if we have a meaningful value
            if default_path:
                os.environ[env_var] = default_path
    except Exception:
        # Silently ignore any failure to set the environment variable
        pass

def extend_cli(self, root_subparsers):
    """Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    # Validate that the passed object behaves like a subparsers container
    if root_subparsers is None or not hasattr(root_subparsers, "add_parser"):
        raise TypeError(
            "root_subparsers must be a subparsers object that provides an add_parser method."
        )

    try:
        # Create a new subparser for the specification commands
        spec_parser = root_subparsers.add_parser(
            "spec",
            help="Specification related commands",
        )
        # Add a sample argument; more can be added by the subclass
        spec_parser.add_argument(
            "--version",
            action="store_true",
            help="Show the current version of the specification library.",
        )
        # Attach a handler; assume the instance implements `_handle_spec`
        if hasattr(self, "_handle_spec"):
            spec_parser.set_defaults(func=self._handle_spec)
        else:
            # If no handler is defined, provide a no-op function
            def _noop(_):
                pass

            spec_parser.set_defaults(func=_noop)
    except Exception as exc:
        # Wrap any exception in a RuntimeError with context for easier debugging
        raise RuntimeError(f"Failed to extend CLI: {exc}") from exc

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")
    path_abs = os.path.abspath(path)
    root_abs = os.path.abspath(root)
    # Ensure root is a prefix of path
    try:
        common = os.path.commonpath([path_abs, root_abs])
    except ValueError as e:
        raise ValueError(f"Invalid paths: {path} and {root}") from e
    if common != root_abs:
        raise ValueError(f"Root '{root}' does not match path '{path}'")
    stripped = os.path.relpath(path_abs, root_abs)
    if stripped == '.':
        stripped = ''
    return stripped
